import csv
import io
path='/root/weoapr2025all.xls'
# Read as utf-16 tab-delimited
with open(path, 'rb') as f:
    text = f.read().decode('utf-16')
# Use csv reader
reader = csv.reader(io.StringIO(text), delimiter='\t')
headers = next(reader)
# Map headers to index
idx = {h:i for i,h in enumerate(headers)}
# target
subjects={'NGDP_R','NGDP_RPCH'}
rows={}
for row in reader:
    if not row or len(row)<len(headers):
        continue
    if row[idx['Country']]=='Georgia' and row[idx['WEO Subject Code']] in subjects:
        rows[row[idx['WEO Subject Code']]] = row
# show year columns
print('found', rows.keys())
for key in subjects:
    if key in rows:
        row=rows[key]
        # columns for years 2000-2027
        years = list(range(2000,2028))
        # find column indexes for years
        # headers contain years as strings
        values={year: row[idx[str(year)]] for year in years}
        print(key, list(values.items())[:3], list(values.items())[-3:])
PY"}

